const input=$json.body??$json;
const cd=input.contract_decision??input.revised_offer_decision??{};
const action=String(cd.action||input.action||"").toLowerCase();
const channel=String(input.channel||input.preferred_channel||"").toLowerCase();
const recipient=String(input.recipient||input.phone||input.email||"").trim();
const mao=Number(cd.dynamic_mao??input.dynamic_mao??input.adjusted_mao??input.mao);
const offer=Number(input.revised_offer_amount??input.offer_price??cd.offer_price);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const dnc=Boolean(input.dnc||input.do_not_contact);
const validChannel=["sms","email"].includes(channel);
const validRecipient=recipient.length>0;
const validMao=Number.isFinite(mao)&&mao>0;
const validOffer=Number.isFinite(offer)&&offer>0;
let status="dispatch_review_required",dispatchState="needs_review",nextWorkflow="WF-126",human=true,reason="dispatch requires review";
if(dnc){status="blocked_dnc";dispatchState="blocked";nextWorkflow="WF-126";human=true;reason="seller is marked do-not-contact";}
else if(blockers.length){status="blocked";dispatchState="blocked";nextWorkflow="WF-126";human=true;reason="active blockers present";}
else if(action==="revised_offer"){
  if(!validMao||!validOffer){status="revised_offer_invalid";dispatchState="needs_review";reason="revised offer or dynamic MAO is missing/invalid";}
  else if(offer>mao){status="revised_offer_above_mao";dispatchState="blocked";nextWorkflow="WF-126";reason="revised offer exceeds protected dynamic MAO";}
  else if(!validChannel||!validRecipient){status="dispatch_missing_channel_or_recipient";dispatchState="needs_review";reason="valid SMS/email channel and recipient are required";}
  else {status="dispatch_ready";dispatchState="ready";nextWorkflow="WF-289";human=true;reason="revised offer is within dynamic MAO and ready for controlled dispatch";}
}
else if(action==="reengage"||action==="walk_away_or_reengage"){
  if(!validChannel||!validRecipient){status="reengagement_missing_channel_or_recipient";dispatchState="needs_review";reason="valid SMS/email channel and recipient are required";}
  else {status="reengagement_ready";dispatchState="ready";nextWorkflow="WF-262";human=true;reason="seller re-engagement is ready for controlled message generation and dispatch";}
}
else if(action==="contract_ready"){
  status="contract_ready";dispatchState="not_dispatch";nextWorkflow="WF-201";human=true;reason="seller terms are ready for contract package validation";}
else {status="no_dispatch_action";dispatchState="no_action";nextWorkflow="WF-126";human=true;reason="decision does not authorize seller dispatch";}
const idempotencyKey=input.idempotency_key||`wf-294:${input.deal_id||"unknown"}:${input.dispatch_id||"none"}:${input.version||1}`;
const dispatchId=input.dispatch_id||`wf294-${input.deal_id||"unknown"}-${input.version||1}`;
return [{json:{...input,workflow:"WF-294",workflow_name:"Revised Offer / Contract Decision → Seller Re-engagement & Offer Dispatch Controller",status,dispatch:{state:dispatchState,dispatch_id:dispatchId,channel:validChannel?channel:null,recipient:validRecipient?recipient:null,offer_price:validOffer?offer:null,dynamic_mao:validMao?mao:null,reason},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"seller_reengagement_offer_dispatch_controller",idempotency_key:idempotencyKey}}}];
